export const LEGACY_CREDENTIAL_NAMESPACE = 'styx'
export const ENV = { recoveryEpoch: 'KLYTH_DELIVERY_RECOVERY_EPOCH', hostWindowHandoff: 'KLYTH_HOST_WINDOW_HANDOFF' } as const
