        session.unattributedAttempts = bump(session.unattributedAttempts, 1, session)
      } else {
        bucket.attempts = bump(bucket.attempts, 1, session)
        bucket.outcomes[attempt.outcome] = bump(bucket.outcomes[attempt.outcome], 1, session)
